  coffee:'<path d="M4 8h12v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4ZM16 9h2a3 3 0 0 1 0 6h-2M7 3v2m5-2v2"/>',
  bag:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M8 9V6a4 4 0 0 1 8 0v3"/>',
  car:'<path d="m5 6-3 7v6h3v-3h14v3h3v-6l-3-7ZM2 12h20M6 14h.01M18 14h.01"/>',
  heart:'<path d="M20.5 5.5a5 5 0 0 0-7 0L12 7l-1.5-1.5a5 5 0 0 0-7 7L12 21l8.5-8.5a5 5 0 0 0 0-7Z"/>',
  play:'<circle cx="12" cy="12" r="9"/><path d="m10 8 6 4-6 4Z"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>', edit:'<path d="m16 3 5 5-12 12-6 1 1-6ZM14 5l5 5"/>',
  settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
  moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>', sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  empty:'<path d="M7 4h10M9 1h6M4 8h16l-3 12H7Z"/>', check:'<path d="m4 12 5 5L20 6"/>',
